#include <atomic>
#ifndef STUDIO_CHEM_SERVICE_HPP
#define STUDIO_CHEM_SERVICE_HPP
// Naming, format conversion, cleanup and 3D all run in an isolated local
// process (RDKit / OPSIN / NISPO). No COM or ActiveX component is used.
namespace chemservice {
inline std::wstring relativeTo(const std::wstring& directory,const std::wstring& value){return value.empty()||value[0]==L'\\'||value[0]==L'/'||(value.size()>1&&value[1]==L':')?value:directory+L"\\"+value;}
inline void write(const std::wstring& path,const std::string& bytes){HANDLE f=CreateFileW(path.c_str(),GENERIC_WRITE,0,0,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,0);if(f==INVALID_HANDLE_VALUE)throw std::runtime_error("无法写入化学服务文件（"+std::to_string(GetLastError())+"）："+U(path));DWORD n=0;BOOL ok=WriteFile(f,bytes.data(),DWORD(bytes.size()),&n,0);CloseHandle(f);if(!ok||n!=bytes.size())throw std::runtime_error("化学服务文件写入不完整");}
inline std::string read(const std::wstring& path,DWORD sharing=FILE_SHARE_READ){HANDLE f=CreateFileW(path.c_str(),GENERIC_READ,sharing,0,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,0);if(f==INVALID_HANDLE_VALUE)throw std::runtime_error("无法读取化学服务结果");DWORD size=GetFileSize(f,0);if(size>32*1024*1024){CloseHandle(f);throw std::runtime_error("化学服务文件过大");}std::string b(size,'\0');DWORD n=0;BOOL ok=ReadFile(f,b.empty()?0:&b[0],size,&n,0);CloseHandle(f);if(!ok||n!=size)throw std::runtime_error("化学服务文件读取不完整");return b;}
inline int python3D(LPWSTR input,LPWSTR output){wchar_t exe[32768],python[32768];GetModuleFileNameW(nullptr,exe,32768);std::wstring path=exe,dir=path.substr(0,path.find_last_of(L"\\/")),ini=dir+L"\\chemistry_backend.ini";GetPrivateProfileStringW(L"Backend",L"Python",L"python.exe",python,32768,ini.c_str());std::wstring script=dir+L"\\chemistry_3d.py",command=L"\""+relativeTo(dir,python)+L"\" \""+script+L"\" \""+input+L"\" \""+output+L"\"";STARTUPINFOW start={};start.cb=sizeof(start);start.dwFlags=STARTF_USESHOWWINDOW;start.wShowWindow=SW_HIDE;PROCESS_INFORMATION p={};if(!CreateProcessW(nullptr,&command[0],0,0,FALSE,CREATE_NO_WINDOW,0,dir.c_str(),&start,&p)){write(output,"三维整理需要配置可用的 Python/RDKit 环境");return 2;}DWORD wait=WaitForSingleObject(p.hProcess,35000);DWORD code=2;if(wait==WAIT_TIMEOUT){TerminateProcess(p.hProcess,4);WaitForSingleObject(p.hProcess,500);write(output,"三维构象计算超时");}else{GetExitCodeProcess(p.hProcess,&code);if(GetFileAttributesW(output)==INVALID_FILE_ATTRIBUTES)write(output,"无法加载 RDKit 三维化学服务");}CloseHandle(p.hThread);CloseHandle(p.hProcess);return int(code);}
inline int pythonOpen(LPWSTR input,LPWSTR output,LPWSTR inMime,LPWSTR outMime,LPWSTR action){
    wchar_t exe[32768]={},python[32768]={},runtime[32768]={};GetModuleFileNameW(nullptr,exe,32768);
    std::wstring path=exe,dir=path.substr(0,path.find_last_of(L"\\/")),ini=dir+L"\\chemistry_backend.ini";
    GetPrivateProfileStringW(L"Backend",L"Python",L"python.exe",python,32768,ini.c_str());
    GetPrivateProfileStringW(L"Backend",L"RuntimeDirectory",dir.c_str(),runtime,32768,ini.c_str());
    std::wstring runtimeDir=relativeTo(dir,runtime),pythonPath=relativeTo(dir,python);
    std::wstring script=runtimeDir+L"\\chemistry_open.py";
    std::wstring command=L"\""+pythonPath+L"\" -X utf8 \""+script+L"\" \""+input+L"\" \""+output+L"\" \""+inMime+L"\" \""+outMime+L"\" \""+action+L"\"";
    STARTUPINFOW start={};start.cb=sizeof(start);start.dwFlags=STARTF_USESHOWWINDOW;start.wShowWindow=SW_HIDE;PROCESS_INFORMATION p={};
    if(!CreateProcessW(nullptr,&command[0],0,0,FALSE,CREATE_NO_WINDOW,0,runtimeDir.c_str(),&start,&p)){write(output,"无法启动本地开源化学引擎，请检查 Python 配置");return 2;}
    DWORD waited=WaitForSingleObject(p.hProcess,35000),code=2;
    if(waited==WAIT_TIMEOUT){TerminateProcess(p.hProcess,4);WaitForSingleObject(p.hProcess,500);write(output,"开源化学计算超时");}
    else{GetExitCodeProcess(p.hProcess,&code);if(GetFileAttributesW(output)==INVALID_FILE_ATTRIBUTES)write(output,"开源化学运行环境不完整，请检查 RDKit、NISPO 和 Java");}
    CloseHandle(p.hThread);CloseHandle(p.hProcess);return int(code);
}
inline int worker(int argc,LPWSTR* argv){if(argc!=7)return 3;std::wstring action=argv[6];if(action==L"conformer3d")return python3D(argv[2],argv[3]);return pythonOpen(argv[2],argv[3],argv[4],argv[5],argv[6]);}
inline bool run(HWND owner,const std::string& input,const std::string& inMime,const std::string& outMime,const std::string& action,std::string* output,const std::atomic<bool>* cancellation=nullptr){if(cancellation&&cancellation->load()){*output="已取消化学服务";return false;}wchar_t exe[32768]={},temporary[32768]={};DWORD length=GetTempPathW(32768,temporary);if(!length||length>=32768){*output="无法获取化学服务临时目录";return false;}std::wstring jobs=std::wstring(temporary)+L"MoleculeStudio-ChemistryJobs";if(!CreateDirectoryW(jobs.c_str(),0)&&GetLastError()!=ERROR_ALREADY_EXISTS){*output="无法创建化学服务临时目录";return false;}GUID guid;CoCreateGuid(&guid);wchar_t uuid[64];StringFromGUID2(guid,uuid,64);std::wstring in=jobs+L"\\"+uuid+L".txt",out=in+L".result.txt";bool ok=false;PROCESS_INFORMATION p={};HANDLE requestJob=CreateJobObjectW(nullptr,nullptr);if(requestJob){JOBOBJECT_EXTENDED_LIMIT_INFORMATION limits={};limits.BasicLimitInformation.LimitFlags=JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;if(!SetInformationJobObject(requestJob,JobObjectExtendedLimitInformation,&limits,sizeof(limits))){CloseHandle(requestJob);requestJob=nullptr;}}try{write(in,input);GetModuleFileNameW(nullptr,exe,32768);std::wstring command=L"\""+std::wstring(exe)+L"\" --chem-service \""+in+L"\" \""+out+L"\" \""+W(inMime)+L"\" \""+W(outMime)+L"\" \""+W(action)+L"\"";STARTUPINFOW si={};si.cb=sizeof(si);si.dwFlags=STARTF_USESHOWWINDOW;si.wShowWindow=SW_HIDE;if(!CreateProcessW(exe,&command[0],0,0,FALSE,CREATE_NO_WINDOW|CREATE_SUSPENDED,0,0,&si,&p))throw std::runtime_error("无法启动化学服务");if(requestJob&&!AssignProcessToJobObject(requestJob,p.hProcess)){CloseHandle(requestJob);requestJob=nullptr;}ResumeThread(p.hThread);if(owner)EnableWindow(owner,FALSE);auto cursor=owner?SetCursor(LoadCursorW(0,MAKEINTRESOURCEW(32514))):nullptr;DWORD start=GetTickCount();bool cancelled=false;
    if(owner)GetAsyncKeyState(VK_ESCAPE);while(WaitForSingleObject(p.hProcess,20)==WAIT_TIMEOUT){if((owner&&(GetAsyncKeyState(VK_ESCAPE)&1))||(cancellation&&cancellation->load()))cancelled=true;MSG msg;while(PeekMessageW(&msg,0,0,0,PM_REMOVE)){if(msg.message==WM_KEYDOWN&&msg.wParam==VK_ESCAPE)cancelled=true;if(msg.message==WM_QUIT){PostQuitMessage(int(msg.wParam));cancelled=true;break;}TranslateMessage(&msg);DispatchMessageW(&msg);}if(cancelled||DWORD(GetTickCount()-start)>40000){TerminateProcess(p.hProcess,4);WaitForSingleObject(p.hProcess,500);break;}}
    DWORD exitCode=0;GetExitCodeProcess(p.hProcess,&exitCode);if(owner)SetCursor(cursor);if(owner){EnableWindow(owner,TRUE);SetForegroundWindow(owner);}if(exitCode==4)throw std::runtime_error(cancelled?"已取消化学服务":"化学服务超时（40 秒）");*output=read(out);ok=exitCode==0;
}catch(const std::exception& e){*output=e.what();if(owner)EnableWindow(owner,TRUE);}if(p.hThread)CloseHandle(p.hThread);if(p.hProcess)CloseHandle(p.hProcess);if(requestJob)CloseHandle(requestJob);DeleteFileW(in.c_str());DeleteFileW(out.c_str());return ok;}
}
#endif
